package database

import (
	"database/sql"
	"fmt"
	"log"
	"os"

	_ "github.com/lib/pq"
	oracle "github.com/godoes/gorm-oracle"
	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var (
	ConnOracle   *gorm.DB
	ConnPostgres *gorm.DB
)

// EnsurePostgresDatabaseExists checks if target database exists on 122.155.164.15:5434, creating it if not.
func EnsurePostgresDatabaseExists() error {
	host := os.Getenv("DB_POSTGRES_HOST")
	port := os.Getenv("DB_POSTGRES_PORT")
	user := os.Getenv("DB_POSTGRES_USER")
	pass := os.Getenv("DB_POSTGRES_PASSWORD")
	targetDB := os.Getenv("DB_POSTGRES_DB_NAME")

	// Connect to default 'postgres' database first
	adminDsn := fmt.Sprintf("host=%s port=%s user=%s password=%s dbname=postgres sslmode=disable", host, port, user, pass)
	db, err := sql.Open("postgres", adminDsn)
	if err != nil {
		return fmt.Errorf("failed to connect to admin postgres: %w", err)
	}
	defer db.Close()

	var exists bool
	query := "SELECT EXISTS(SELECT 1 FROM pg_database WHERE datname = $1)"
	err = db.QueryRow(query, targetDB).Scan(&exists)
	if err != nil {
		return fmt.Errorf("failed to check database existence: %w", err)
	}

	if !exists {
		log.Printf("Database '%s' does not exist. Creating new database...", targetDB)
		_, err = db.Exec(fmt.Sprintf("CREATE DATABASE %s", targetDB))
		if err != nil {
			return fmt.Errorf("failed to create database '%s': %w", targetDB, err)
		}
		log.Printf("Successfully created database '%s'!", targetDB)
	} else {
		log.Printf("Database '%s' already exists on target PostgreSQL server.", targetDB)
	}

	return nil
}

// ConnectPostgres initializes GORM connection to the target PostgreSQL database
func ConnectPostgres() (*gorm.DB, error) {
	if err := EnsurePostgresDatabaseExists(); err != nil {
		return nil, err
	}

	host := os.Getenv("DB_POSTGRES_HOST")
	port := os.Getenv("DB_POSTGRES_PORT")
	user := os.Getenv("DB_POSTGRES_USER")
	pass := os.Getenv("DB_POSTGRES_PASSWORD")
	dbName := os.Getenv("DB_POSTGRES_DB_NAME")

	dsn := fmt.Sprintf("host=%s port=%s user=%s password=%s dbname=%s sslmode=disable TimeZone=Asia/Bangkok",
		host, port, user, pass, dbName)

	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Info),
	})
	if err != nil {
		return nil, fmt.Errorf("failed to connect to PostgreSQL '%s': %w", dbName, err)
	}

	ConnPostgres = db
	log.Println("Connected to PostgreSQL DB successfully")
	return ConnPostgres, nil
}

// ConnectOracle initializes GORM connection to existing Core ERP Oracle DB
func ConnectOracle() (*gorm.DB, error) {
	url := os.Getenv("DB_ORACLE_URL")
	port := 1521
	srvName := os.Getenv("DB_ORACLE_SERVICE_NAME")
	user := os.Getenv("DB_ORACLE_USER")
	pass := os.Getenv("DB_ORACLE_PASSWORD")

	connStr := oracle.BuildUrl(url, port, srvName, user, pass, nil)
	db, err := gorm.Open(oracle.Open(connStr), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Info),
	})
	if err != nil {
		return nil, fmt.Errorf("failed to connect to Oracle DB: %w", err)
	}

	ConnOracle = db
	log.Println("Connected to Oracle ERP DB successfully")
	return ConnOracle, nil
}

package ingestion

import (
	"fmt"
	"log"
	"os"
	"strconv"
	"time"

	"gorm.io/gorm"
)

type Extractor struct {
	oraDB       *gorm.DB
	pgDB        *gorm.DB
	maxDays     int
	safetyDryRun bool
}

func NewExtractor(oraDB, pgDB *gorm.DB) *Extractor {
	daysStr := os.Getenv("DATA_EXTRACTION_MAX_DAYS")
	maxDays, err := strconv.Atoi(daysStr)
	if err != nil || maxDays <= 0 || maxDays > 7 {
		// Strict Security Guardrail: Force max 7 days test scope as instructed
		maxDays = 7
	}

	dryRun := os.Getenv("SAFETY_DRY_RUN") == "true"

	return &Extractor{
		oraDB:        oraDB,
		pgDB:         pgDB,
		maxDays:      maxDays,
		safetyDryRun: dryRun,
	}
}

// TestOracleConnectionQueries verifies query against Oracle DB strictly restricted to <= 7 days
func (e *Extractor) TestOracleConnectionQueries() error {
	log.Printf("==========================================================")
	log.Printf(" [SAFETY GUARDRAIL ENGAGED]")
	log.Printf(" Data query scope LIMITED to MAX %d DAYS (SYSDATE - %d)", e.maxDays, e.maxDays)
	log.Printf(" Safety Dry-Run Mode: %v (No full insertion into DB)", e.safetyDryRun)
	log.Printf("==========================================================")

	// 1. Test Query Master Shop Count
	var shopCount int64
	if err := e.oraDB.Table("shop").Where("active = 'Y'").Count(&shopCount).Error; err != nil {
		return fmt.Errorf("oracle shop count test failed: %w", err)
	}
	log.Printf("[Oracle ERP Test] Active Shops Count: %d", shopCount)

	// 2. Test Query Product Count
	var productCount int64
	if err := e.oraDB.Table("product").Where("status = 'ACTIVE'").Count(&productCount).Error; err != nil {
		return fmt.Errorf("oracle product count test failed: %w", err)
	}
	log.Printf("[Oracle ERP Test] Active Products Count: %d", productCount)

	// 3. Test Query Sales Transaction (STRICT 7 DAYS FILTER)
	startDate := time.Now().AddDate(0, 0, -e.maxDays).Format("2006-01-02")
	var salesCount int64
	querySales := fmt.Sprintf("sell_date >= DATE '%s'", startDate)

	if err := e.oraDB.Table("sell").Where(querySales).Count(&salesCount).Error; err != nil {
		return fmt.Errorf("oracle sales test (7 days limit) failed: %w", err)
	}
	log.Printf("[Oracle ERP Test] Sales Count in Last %d Days (%s to now): %d records", e.maxDays, startDate, salesCount)

	if e.safetyDryRun {
		log.Println("[SAFETY GUARDRAIL] Full data ingestion skipped to protect Core ERP Database as instructed.")
	}

	return nil
}

